def _brain_post(path: str, payload: dict, timeout: float = 8.0) -> dict:
    with httpx.Client(timeout=timeout) as c:
        r = c.post(f"{BRAIN}{path}", json=payload)
        r.raise_for_status()
        return r.json()

def _clip(obj, limit: int = 20000) -> str:
    s = json.dumps(obj, ensure_ascii=False, indent=1, default=str)
    return s if len(s) <= limit else s[:limit] + "\n…[truncated]"
